const fsp = require('node:fs').promises
const f = await fsp.open('/data/f.txt', 'r')
const buf = Buffer.alloc(3)
const { bytesRead } = await f.read(buf, 0, 3, 2)
console.log(bytesRead, JSON.stringify(buf.toString()))
const tail = Buffer.alloc(10)
const end = await f.read(tail, 0, 10, 10)
console.log(end.bytesRead, JSON.stringify(tail.subarray(0, end.bytesRead).toString()))
console.log((await f.stat()).size)
await f.close()
for await (const line of (await fsp.open('/data/f.txt')).readLines()) console.log(line)

