const fd = os.open('/data/f.txt', os.O_RDONLY)
const buf = new ArrayBuffer(5)
const text = (n) => String.fromCharCode(...new Uint8Array(buf, 0, n))
console.log(os.seek(fd, -6, std.SEEK_END), text(os.read(fd, buf, 0, 5)))
console.log(os.seek(fd, 0, std.SEEK_CUR))
console.log(os.seek(fd, 4, std.SEEK_SET), text(os.read(fd, buf, 0, 3)))
console.log(os.close(fd))
